settings._cssCustom:
@media (max-width: 48rem) {
  .c-event-landing .c-event-landing__hero-inner,
  .c-event-landing .c-event-landing__info-inner,
  .c-event-landing .c-event-landing__pricing-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-l);
  }

  .c-event-landing .c-event-landing__hero {
    padding-block-start: var(--section-space-m);
  }

  .c-event-landing .c-event-landing__hero-media {
    order: -1;
  }

  .c-event-landing .c-event-landing__hero-media img {
    aspect-ratio: 16 / 10;
  }

  .c-event-landing .c-event-landing__facts-inner,
  .c-event-landing .c-event-landing__gallery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 34rem) {
  .c-event-landing .c-event-landing__facts-inner,
  .c-event-landing .c-event-landing__quotes,
  .c-event-landing .c-event-landing__gallery-grid,
  .c-event-landing .c-event-landing__participants {
    grid-template-columns: minmax(0, 1fr);
  }

  .c-event-landing .c-event-landing__ticket {
    grid-template-columns: minmax(0, 1fr);
  }

  .c-event-landing .c-event-landing__ticket-buy {
    grid-column: 1;
    justify-self: start;
  }
}
@media (prefers-reduced-motion: reduce) {
  .c-event-landing *,
  .c-event-landing *::before,
  .c-event-landing *::after {
    scroll-behavior: auto;
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
    transition-duration: 0.01ms;
  }
}
@scope (html:has(.c-event-landing)) {
  html, :scope, body { overflow-x: clip; }
}
.c-event-landing {
  --event-paper: var(--white);
  --event-surface: var(--base-ultra-light);
  --event-ink: var(--base-ultra-dark);
  --event-muted: var(--text-dark-muted);
  --event-on-accent: var(--text-light);
  --event-accent: var(--primary);
  --event-gutter: var(--gutter);
  --event-section-space: var(--section-space-m);
  --event-content-width: var(--content-width);
  color: var(--event-ink);
  background: var(--event-paper);
}
.c-event-landing :where(p, figure, blockquote) {
  margin-block: 0;
}
.c-event-landing__hero {
  padding-inline: var(--event-gutter);
}
.c-event-landing__facts {
  padding-inline: var(--event-gutter);
}
.c-event-landing__proof {
  padding-inline: var(--event-gutter);
}
.c-event-landing__gallery {
  padding-inline: var(--event-gutter);
}
.c-event-landing__cta {
  padding-inline: var(--event-gutter);
}
.c-event-landing__info {
  padding-inline: var(--event-gutter);
}
.c-event-landing__pricing {
  padding-inline: var(--event-gutter);
}
.c-event-landing__hero {
  padding-block: var(--section-space-m);
  background: var(--event-surface);
}
.c-event-landing__hero-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-xl);
  align-items: center;
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__info-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-xl);
  align-items: center;
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__pricing-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-xl);
  align-items: center;
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__hero-copy {
  display: grid;
  justify-items: start;
  gap: var(--space-m);
  min-width: 0;
}
.c-event-landing__info-copy {
  display: grid;
  justify-items: start;
  gap: var(--space-m);
  min-width: 0;
}
.c-event-landing__cta-copy {
  display: grid;
  justify-items: start;
  gap: var(--space-m);
  min-width: 0;
}
.c-event-landing__title {
  max-width: 16ch;
  font-size: var(--h1);
  line-height: 1.08;
  text-wrap: balance;
  overflow-wrap: break-word;
  min-width: 0;
}
.c-event-landing__lede {
  max-width: 65ch;
  color: var(--event-muted);
  font-size: var(--text-l);
  line-height: 1.55;
}
.c-event-landing__hero-media {
  min-width: 0;
  overflow: hidden;
  background: var(--event-surface);
}
.c-event-landing__info-media {
  min-width: 0;
  overflow: hidden;
  background: var(--event-surface);
}
.c-event-landing__hero-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.c-event-landing__info-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.c-event-landing__gallery-grid img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.c-event-landing__hero-media img {
  aspect-ratio: 4 / 3;
  max-height: calc(var(--section-space-l) * 3);
}
.c-event-landing__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-s);
  align-items: center;
}
.c-event-landing__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--space-l);
  padding: var(--space-xs) var(--space-m);
  border: 1px solid var(--event-ink);
  background: var(--event-ink);
  color: var(--event-on-accent);
  font-size: var(--text-m);
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
}
.c-event-landing__button:hover {
  border-color: var(--event-accent);
  background: var(--event-accent);
}
.c-event-landing__button:focus-visible {
  outline: 2px solid var(--event-ink);
  outline-offset: var(--space-3xs, 0.25rem);
}
.c-event-landing__button:active {
  background: var(--event-accent);
}
.c-event-landing__button:disabled {
  border-color: var(--event-muted);
  background: var(--event-muted);
  cursor: not-allowed;
}
.c-event-landing__button[aria-disabled="true"] {
  border-color: var(--event-muted);
  background: var(--event-muted);
  cursor: not-allowed;
}
.c-event-landing__facts {
  padding-block: var(--space-l);
}
.c-event-landing__facts-inner {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-s);
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__fact {
  display: grid;
  align-content: start;
  gap: var(--space-xs);
  min-width: 0;
  padding: var(--space-m);
  border-top: 2px solid var(--event-accent);
  background: var(--event-surface);
}
.c-event-landing__fact-label {
  color: var(--event-muted);
  font-size: var(--text-s);
  line-height: 1.4;
}
.c-event-landing__fact-value {
  font-size: var(--h3);
  line-height: 1.2;
  overflow-wrap: break-word;
  min-width: 0;
}
.c-event-landing__proof {
  padding-block: var(--event-section-space);
}
.c-event-landing__gallery {
  padding-block: var(--event-section-space);
}
.c-event-landing__info {
  padding-block: var(--event-section-space);
}
.c-event-landing__pricing {
  padding-block: var(--event-section-space);
}
.c-event-landing__section-inner {
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__section-title {
  max-width: 22ch;
  margin-block-end: var(--space-l);
  font-size: var(--h2);
  line-height: 1.12;
  text-wrap: balance;
  overflow-wrap: break-word;
  min-width: 0;
}
.c-event-landing__quotes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-m);
}
.c-event-landing__quote {
  display: grid;
  align-content: start;
  gap: var(--space-m);
  min-width: 0;
  padding: var(--space-l);
  border-block: 1px solid var(--event-accent);
}
.c-event-landing__quote-text {
  color: var(--event-ink);
  font-size: var(--text-l);
  line-height: 1.55;
}
.c-event-landing__quote-author {
  color: var(--event-muted);
  font-size: var(--text-s);
  font-style: normal;
}
.c-event-landing__gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-s);
}
.c-event-landing__gallery-grid img {
  aspect-ratio: 4 / 3;
}
.c-event-landing__cta {
  padding-block: var(--section-space-m);
  background: var(--event-ink);
  color: var(--event-on-accent);
}
.c-event-landing__cta-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-l);
  width: min(100%, var(--event-content-width));
  margin-inline: auto;
}
.c-event-landing__cta-copy {
  flex: 1 1 30ch;
}
.c-event-landing__cta .c-event-landing__section-title {
  margin-block-end: 0;
}
.c-event-landing__cta .c-event-landing__button {
  border-color: var(--event-paper);
  background: var(--event-paper);
  color: var(--event-ink);
}
.c-event-landing__cta .c-event-landing__button:hover {
  border-color: var(--event-accent);
  background: var(--event-accent);
  color: var(--event-on-accent);
}
.c-event-landing__cta .c-event-landing__button:active {
  border-color: var(--event-accent);
  background: var(--event-accent);
  color: var(--event-on-accent);
}
.c-event-landing__info-inner {
  align-items: start;
}
.c-event-landing__info-media img {
  aspect-ratio: 4 / 3;
}
.c-event-landing__body {
  max-width: 68ch;
  color: var(--event-muted);
  font-size: var(--text-m);
  line-height: 1.7;
}
.c-event-landing__participants {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-s);
  margin-block-start: var(--space-l);
}
.c-event-landing__pricing {
  background: var(--event-surface);
}
.c-event-landing__pricing-inner {
  align-items: start;
}
.c-event-landing__ticket-list {
  display: grid;
  gap: var(--space-s);
  min-width: 0;
}
.c-event-landing__ticket {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-m);
  align-items: center;
  min-width: 0;
  padding: var(--space-m);
  border-block: 1px solid var(--event-muted);
  background: var(--event-paper);
}
.c-event-landing__ticket-main {
  display: grid;
  gap: var(--space-xs);
  min-width: 0;
}
.c-event-landing__ticket-title {
  font-size: var(--h3);
  line-height: 1.2;
  overflow-wrap: break-word;
  min-width: 0;
}
.c-event-landing__ticket-description {
  color: var(--event-muted);
  font-size: var(--text-s);
  line-height: 1.5;
}
.c-event-landing__ticket-price {
  font-size: var(--text-l);
  font-weight: 600;
  white-space: nowrap;
}
.c-event-landing__ticket-buy {
  grid-column: 2;
  justify-self: end;
}
.c-event-landing__empty {
  padding: var(--space-m);
  border-inline-start: 2px solid var(--event-accent);
  color: var(--event-muted);
}
.c-event-landing__hero-inner:not(:has(.c-event-landing__hero-media)) {
  grid-template-columns: minmax(0, 1fr);
}
.c-event-landing__info-inner:not(:has(.c-event-landing__info-media)) {
  grid-template-columns: minmax(0, 1fr);
}
.c-event-landing__button--secondary {
  background: transparent;
  color: var(--event-ink);
}
.c-event-landing__button:hover {
  color: var(--event-ink);
}
.c-event-landing__button:active {
  color: var(--event-ink);
}
.c-event-landing__cta .c-event-landing__section-title {
  color: var(--event-on-accent);
}
.c-event-landing__cta .c-event-landing__button:hover {
  color: var(--event-ink);
}
.c-event-landing__cta .c-event-landing__button:active {
  color: var(--event-ink);
}
.c-event-landing__cta .c-event-landing__button:focus-visible {
  outline-color: var(--event-paper);
}
.c-event-landing__ticket-buy :is(a,button,input):focus-visible {
  outline: 2px solid var(--event-ink);
  outline-offset: var(--space-xs);
}
.c-event-landing__video :is(a,button):focus-visible {
  outline: 2px solid var(--event-ink);
  outline-offset: var(--space-xs);
}
.c-event-landing__info {
  row-gap: var(--space-xl);
}
.c-event-landing__pricing-copy {
  display: grid;
  gap: var(--space-m);
}
.c-event-landing__ticket-price .price {
  color: var(--event-ink);
  opacity: 1;
}
.c-event-landing__ticket-price .price :is(del,ins,bdi,span) {
  color: var(--event-ink);
  opacity: 1;
}
.c-event-landing__ticket-buy {
  grid-column: 1 / -1;
  justify-self: start;
}
.c-event-landing__cta-inner {
  flex-direction: row;
}
.c-event-landing__quote-text {
  background: transparent;
  border: 0;
  padding: 0;
  font: inherit;
  font-size: var(--text-l);
  line-height: 1.55;
}
img.c-event-landing__info-media {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}
